import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"分表分库","description":"","frontmatter":{},"headers":[],"relativePath":"database/mysql/basic/sharding.md","filePath":"database/mysql/basic/sharding.md"}`),a={name:`database/mysql/basic/sharding.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="分表分库" tabindex="-1">分表分库 <a class="header-anchor" href="#分表分库" aria-label="Permalink to “分表分库”">​</a></h1><ul><li>是应对数据库性能瓶颈的核心方案，通过将数据分散到多个表或数据库中，解决单表 / 单库数据量过大导致的查询缓慢、写入瓶颈等问题。</li></ul><h2 id="为什么需要分表分库" tabindex="-1">为什么需要分表分库？ <a class="header-anchor" href="#为什么需要分表分库" aria-label="Permalink to “为什么需要分表分库？”">​</a></h2><ul><li>当数据库达到一定规模（如单表千万级以上），会面临以下问题： <ul><li>查询性能下降：索引树过大，扫描 / IO 成本高，即使走索引也可能变慢。</li><li>写入压力大：单表写入并发高，锁竞争激烈（如行锁、表锁）。</li><li>存储瓶颈：单库磁盘空间有限，备份 / 恢复耗时。</li><li>扩展受限：单库无法利用多服务器资源，垂直扩展（升级硬件）成本高。</li></ul></li></ul><h2 id="分库" tabindex="-1">分库 <a class="header-anchor" href="#分库" aria-label="Permalink to “分库”">​</a></h2><ul><li>分库是将一个数据库中的表切分成多个数据库（通常在不同服务器），每个数据库存储不同的表数据。</li><li>分库的目的是将数据库的压力分散到多个数据库中，从而提高数据库的性能和吞吐量。</li><li>示例： <ul><li>假设一个电商数据库包含用户表、订单表、商品表等。 <ul><li>将用户表以及相关表 (如用户住址表、用户vip表等) 切分到一个数据库中，专门管理用户信息的。</li><li>将商品表以及相关表（如商品属性表、商品分类表等）切分到一个数据库中，专门管理商品信息的。</li><li>将订单表以及相关表（如订单信息表、订单商品表等）切分到一个数据库中，专门管理订单信息的。</li></ul></li></ul></li></ul><h2 id="分表" tabindex="-1">分表 <a class="header-anchor" href="#分表" aria-label="Permalink to “分表”">​</a></h2><ul><li>分表是将一个表中的记录切分到多个结构相同的表中。</li><li>分表的目的是将表的数据分散到多个表中，从而提高表的查询性能和写入性能。</li><li>示例： <ul><li>假设一个订单表包含了所有订单的信息，当订单量不断增加时，单表会变得非常庞大。 <ul><li>可以将订单表按订单日期进行切分，每个月的订单数据存储在一个独立的表中，例如 <code>order_202301</code>、<code>order_202302</code> 等。</li><li>每个月的订单表都可以独立进行查询和写入操作，避免了对单表的压力。</li></ul></li></ul></li></ul><h2 id="拆分策略" tabindex="-1">拆分策略 <a class="header-anchor" href="#拆分策略" aria-label="Permalink to “拆分策略”">​</a></h2><h3 id="水平切分" tabindex="-1">水平切分 <a class="header-anchor" href="#水平切分" aria-label="Permalink to “水平切分”">​</a></h3><ul><li>按行拆分，将表中不同行的数据分散到多个表 / 库，表结构不变。</li></ul><h4 id="范围拆分" tabindex="-1">范围拆分 <a class="header-anchor" href="#范围拆分" aria-label="Permalink to “范围拆分”">​</a></h4><ul><li>按时间：如按月份分表：order_202301、order_202302；</li><li>按ID分表：1-100万在表A，101-200万在表B</li><li>优点：规则简单，便于扩容；</li><li>缺点：可能存在数据倾斜，例如双11活动，订单集中这天。</li></ul><h4 id="哈希拆分" tabindex="-1">哈希拆分 <a class="header-anchor" href="#哈希拆分" aria-label="Permalink to “哈希拆分”">​</a></h4><ul><li>对关键字段（如用户 ID）哈希取模（如 user_id % 4 分为 4 个分片）。</li><li>优点：数据分布均匀，避免热点；</li><li>缺点：扩容需重新哈希（可通过一致性哈希缓解），历史数据迁移复杂。</li></ul><h4 id="列表拆分" tabindex="-1">列表拆分 <a class="header-anchor" href="#列表拆分" aria-label="Permalink to “列表拆分”">​</a></h4><ul><li>按枚举值拆分（如按地区分表：order_beijing、order_shanghai）。</li><li>优点：针对性优化（如地区业务隔离）；</li><li>缺点：枚举值过多时分片数量爆炸。</li></ul><h4 id="组合拆分" tabindex="-1">组合拆分 <a class="header-anchor" href="#组合拆分" aria-label="Permalink to “组合拆分”">​</a></h4><ul><li>结合多种规则（如先按范围分库，库内再按哈希分表）。</li></ul><h3 id="垂直切分" tabindex="-1">垂直切分 <a class="header-anchor" href="#垂直切分" aria-label="Permalink to “垂直切分”">​</a></h3><ul><li>按列拆分，将表中不同字段拆分到不同表 / 库，通常按业务关联性拆分。</li><li>将 “高频访问字段” 和 “低频 / 大字段” 分离。</li></ul><h4 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h4><ul><li>原表 user（含 id, name, age, avatar(大字段), description(长文本)）</li><li>垂直切分后： <ul><li>user_base（含 id, name, age）</li><li>user_detail（含 id, avatar, description）</li></ul></li></ul><h4 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to “优点”">​</a></h4><ul><li>减少单表数据量，提升查询效率（高频表字段少，索引更高效）；</li><li>隔离大字段 IO（如图片、长文本），避免影响核心业务。</li></ul><h4 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to “缺点”">​</a></h4><ul><li>多表关联查询变复杂（需跨表 join）；</li><li>拆分过度会导致业务逻辑冗余。</li></ul><h2 id="实现方式" tabindex="-1">实现方式 <a class="header-anchor" href="#实现方式" aria-label="Permalink to “实现方式”">​</a></h2><h3 id="客户端方案" tabindex="-1">客户端方案 <a class="header-anchor" href="#客户端方案" aria-label="Permalink to “客户端方案”">​</a></h3><ul><li>在应用程序中直接处理分片逻辑（如路由、聚合），需开发人员手动实现。</li><li>优点：简单直接，无需数据库支持；</li><li>缺点：开发成本高，维护成本高（需手动处理分片逻辑）。</li></ul><h3 id="中间件方案" tabindex="-1">中间件方案 <a class="header-anchor" href="#中间件方案" aria-label="Permalink to “中间件方案”">​</a></h3><ul><li>通过独立的中间件统一处理分片逻辑，对应用透明。</li></ul><h4 id="中间件" tabindex="-1">中间件 <a class="header-anchor" href="#中间件" aria-label="Permalink to “中间件”">​</a></h4><ul><li>ShardingSphere（国产，功能全面，支持分库分表、读写分离、分布式事务）；</li><li>MyCat（基于 Cobar，轻量级，适合中小规模）；</li><li>Vitess（谷歌开源，适合超大规模集群，支持 MySQL/PostgreSQL）。</li></ul><h4 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to “工作原理”">​</a></h4><ul><li>应用通过中间件访问数据库（如连接 ShardingSphere 的代理端口）；</li><li>中间件解析 SQL，根据分片规则路由到目标表 / 库；</li><li>汇总多分片结果，返回给应用。</li></ul><h4 id="优点-1" tabindex="-1">优点 <a class="header-anchor" href="#优点-1" aria-label="Permalink to “优点”">​</a></h4><ul><li>无业务侵入，规则动态配置，支持复杂场景（如跨分片 join）；</li></ul><h4 id="缺点-1" tabindex="-1">缺点 <a class="header-anchor" href="#缺点-1" aria-label="Permalink to “缺点”">​</a></h4><ul><li>引入中间件开销，需额外维护。</li></ul><h2 id="关键挑战" tabindex="-1">关键挑战 <a class="header-anchor" href="#关键挑战" aria-label="Permalink to “关键挑战”">​</a></h2><h3 id="跨分片查询" tabindex="-1">跨分片查询 <a class="header-anchor" href="#跨分片查询" aria-label="Permalink to “跨分片查询”">​</a></h3><ul><li>问题：JOIN、GROUP BY、ORDER BY 涉及多分片时，性能差。</li><li>方案：尽量避免跨分片查询；中间件支持分片键关联查询；预聚合结果（如用 ES 存储统计数据）。</li></ul><h3 id="分布式事务" tabindex="-1">分布式事务 <a class="header-anchor" href="#分布式事务" aria-label="Permalink to “分布式事务”">​</a></h3><ul><li>问题：跨库操作需保证 ACID（如转账涉及两个库的账户表）。</li><li>方案：采用最终一致性（如 TCC、SAGA 模式）；ShardingSphere 支持 XA/Seata 等分布式事务。</li></ul><h3 id="扩容与迁移" tabindex="-1">扩容与迁移 <a class="header-anchor" href="#扩容与迁移" aria-label="Permalink to “扩容与迁移”">​</a></h3><ul><li>问题：分片数量不足时，需新增分片并迁移数据，避免服务中断。</li><li>方案：提前规划分片数量（预留冗余）；使用中间件的在线扩容功能（如 ShardingSphere 的弹性伸缩）；双写迁移（旧分片写入时同步到新分片）。</li></ul><h3 id="全局-id" tabindex="-1">全局 ID <a class="header-anchor" href="#全局-id" aria-label="Permalink to “全局 ID”">​</a></h3><ul><li>问题：分表后自增 ID 重复（单表自增无法保证全局唯一）。</li><li>方案：UUID、雪花算法（Snowflake）、数据库号段模式（如 Leaf）、Redis 自增。</li></ul><h3 id="索引设计" tabindex="-1">索引设计 <a class="header-anchor" href="#索引设计" aria-label="Permalink to “索引设计”">​</a></h3><ul><li>问题：分片后索引仅在单分片内有效，全局索引维护难。</li><li>方案：优先按分片键查询；非分片键查询可通过中间件路由到所有分片（性能差，需谨慎）；引入外部索引（如 ES）。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to “最佳实践”">​</a></h2><ul><li><p>先优化，后拆分：单表未达瓶颈（如百万级）时，优先通过索引、SQL 优化、读写分离解决，避免过度设计。</p></li><li><p>分片键选择：尽量使用高频查询的字段（如用户 ID、订单 ID），避免跨分片查询。</p></li><li><p>控制分片粒度：分表数量不宜过多（如单库表数不超过 100），否则元数据管理复杂。</p></li><li><p>数据倾斜监控：定期检查各分片数据量 / 访问量，避免热点分片（如某用户数据集中在一个分片）。</p></li><li><p>备份与恢复：分库分表后，需针对每个分片单独备份，或使用工具统一管理（如 Percona XtraBackup）。</p></li></ul>`,53)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};